# Generated by manage.py generate_test_cases.
"""Membership and session-state enforcement for admission credentials."""

import json
from unittest.mock import patch

import jwt
from django.http import HttpResponse

from bloomerp.communication.builtins.instant_messaging.definition import (
    IMCallCapabilities,
)
from bloomerp.models.communication.conferencing import ConferenceAttendance
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.conferencing.fixtures import CallFixtures


class TestJoinComponent(CallFixtures, BloomerpComponentTestCase):
    view_name = "components_conferencing_join"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover scoped admission and current source access rather than historical membership alone."""
        return [
            RequestScenario(
                name="Provider can allow camera while denying screen capture",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_no_screen,
                cleanup=self.restore_screen_capabilities,
                expected=ExpectedResult(response_validators=self.no_screen_credentials),
            ),
            RequestScenario(
                name="Call identity reuses provider presentation without exposing addresses",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_provider_identity,
                expected=ExpectedResult(response_validators=self.provider_identity),
            ),
            RequestScenario(
                name="Invitee receives scoped credentials",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_session,
                expected=ExpectedResult(response_validators=self.valid_credentials),
            ),
            RequestScenario(
                name="Revoked member cannot join",
                method="POST",
                user=self.normal_user,
                prepare=self.revoke_member,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Closed session cannot join",
                method="POST",
                user=self.normal_user,
                prepare=self.ended_session,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Login required",
                method="POST",
                prepare=self.prepare_session,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="GET does not issue tokens",
                user=self.normal_user,
                prepare=self.prepare_session,
                expected=ExpectedResult(status_code=405),
            ),
        ]

    def valid_credentials(self, response: HttpResponse) -> bool:
        """Verify the real token and ensure credential issuance is not counted as attendance."""
        data = json.loads(response.content)
        claims = jwt.decode(
            data["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return (
            claims["video"]["room"] == self.session.livekit_room_name
            and claims["sub"] == data["identity"]
            and data["driver"] == "livekit"
            and data["can_video"] == "true"
            and data["can_screen_share"] == "true"
            and "screen_share" in claims["video"]["canPublishSources"]
            and data["can_end"] == "false"
            and len(data["identity"]) <= 255
            and not ConferenceAttendance.objects.exists()
            and response["Cache-Control"] == "private, no-store"
        )

    def prepare_provider_identity(self, scenario: RequestScenario) -> None:
        """Provide an IM presentation override after creating an authorized session."""
        self.prepare_session(scenario)
        self.enterContext(
            patch(
                "bloomerp.communication.builtins.instant_messaging.definition.IMProviderDefinition.resolve_identity",
                return_value={
                    "displayName": "Chat Identity",
                    "avatar": "/media/chat-avatar.png",
                    "address": "private@example.test",
                },
            )
        )

    def provider_identity(self, response: HttpResponse) -> bool:
        """Verify names and avatars match IM while metadata contains no contact address."""
        claims = jwt.decode(
            json.loads(response.content)["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return (
            claims["name"] == "Chat Identity"
            and json.loads(claims["metadata"])
            == {
                "displayName": "Chat Identity",
                "avatar": "/media/chat-avatar.png",
                "initials": "CI",
            }
            and claims["video"]["canUpdateOwnMetadata"] is False
        )

    def prepare_no_screen(self, scenario: RequestScenario) -> None:
        """Resolve camera access independently from screen sharing after admission."""
        self.prepare_session(scenario)
        self.screen_capability_patch = patch(
            "bloomerp.communication.builtins.instant_messaging.calling.call_capabilities",
            return_value=IMCallCapabilities(audio=True, video=True),
        )
        self.screen_capability_patch.start()
        self.addCleanup(self.screen_capability_patch.stop)

    def restore_screen_capabilities(self, scenario: RequestScenario) -> None:
        """Remove the capability override before the next declarative scenario."""
        self.screen_capability_patch.stop()

    def no_screen_credentials(self, response: HttpResponse) -> bool:
        """Verify the UI capability and signed grants both deny screen publication."""
        data = json.loads(response.content)
        claims = jwt.decode(
            data["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return data["can_screen_share"] == "false" and set(
            claims["video"]["canPublishSources"]
        ) == {"microphone", "camera"}
